<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$rows=$pdo?$pdo->query('SELECT path,COUNT(*) views,MAX(created_at) last_view FROM page_views GROUP BY path ORDER BY views DESC LIMIT 100')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page Views</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Page View Reports</h1><p><a href="dashboard.php">Dashboard</a></p><div class="card"><table style="width:100%"><tr><th>Path</th><th>Views</th><th>Last view</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['path'])?></td><td><?=e((string)$r['views'])?></td><td><?=e($r['last_view'])?></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">No page views found.</p><?php endif;?></div></main></body></html>
